local addonName, addonTable = "Auctionator", AtrNS; 
local zc = addonTable.zc;

-----------------------------------------


local gAtr_MI = "";

-----------------------------------------

function Atr_GetBonding (itemID, vpstr)

	if (itemID == nil) then
		return 0;
	end

	if (itemID == 43015 or itemID == 34753 or itemID == 43480 or itemID == 43478) then
		return 0;
	end


	if (vpstr == nil) then
		vpstr = gAtr_MI;
	end

	local bonding = 0;

	local x = ((itemID-1) * 2) + 2;
	
	if (x <= string.len (vpstr)) then

		local s = string.sub (vpstr, x, x);

		bonding = zc.dec64 (s);
	end

	return bonding;
end

